"""Verbatim trigger evaluator: queue fixed responses on tool and skill events.

Tool ``on_success`` / ``on_failure`` fire after builder tools run; skill ``utter:``
entries fire on ``on: activate`` and on a ``when:`` condition expression. Queued
responses are emitted by the orchestrator in the same LLM turn
(``ResponseMode.CONTINUE``) before the next iteration.
"""

from __future__ import annotations

from typing import TYPE_CHECKING, Any, List, Optional

import structlog

from rasa.mantle.orchestration.responses import (
    AgentResponse,
    ResolveUtteranceFunc,
    ResponseMode,
    button_source_scope_fields,
)
from rasa.mantle.orchestration.tool_execution.payload import (
    error_from_tool_payload,
)
from rasa.mantle.skills.catalog import SkillCatalog
from rasa.mantle.skills.conditions import (
    Condition,
    ConditionEvaluationError,
    GatedTool,
    evaluate_expression,
)

if TYPE_CHECKING:
    from rasa.mantle.state.tracker_handle import TrackerHandle

structlogger = structlog.get_logger()


class VerbatimTriggerEvaluator:
    """Queue verbatim responses for tool outcomes and skill utter triggers."""

    def __init__(
        self,
        skill_catalog: SkillCatalog,
        resolve_utterance: ResolveUtteranceFunc,
    ) -> None:
        self._skill_catalog = skill_catalog
        self._resolve_utterance = resolve_utterance
        self._responses_this_turn: List[AgentResponse] = []

    def begin_user_turn(self) -> None:
        """Reset per-turn verbatim state at the start of a user turn."""
        self._responses_this_turn = []

    def consume_responses(self) -> List[AgentResponse]:
        """Return and clear verbatim responses queued during the turn."""
        responses = self._responses_this_turn
        self._responses_this_turn = []
        return responses

    def queue_tool_outcome(
        self,
        *,
        tool_name: str,
        raw_result: str | None,
        tracker_handle: TrackerHandle,
    ) -> None:
        """Queue ``on_success`` / ``on_failure`` when *tool_name* has a gate."""
        tool_gate = self._tool_gate_for(tool_name, tracker_handle)
        if tool_gate is None:
            return

        is_error, _ = error_from_tool_payload(raw_result)
        response_name = tool_gate.on_failure if is_error else tool_gate.on_success
        if not response_name:
            return

        self._queue_response(
            response_name=response_name,
            tracker_handle=tracker_handle,
            source="tool_outcome",
            tool_name=tool_name,
            is_error=is_error,
        )

    def queue_activate_triggers(
        self, skill_id: str, tracker_handle: TrackerHandle
    ) -> None:
        """Queue skill ``utter:`` entries with ``on: activate`` for *skill_id*."""
        skill = self._skill_catalog.skill_by_id(skill_id)
        if skill is None:
            return

        frame = tracker_handle.active_frame
        if frame is None:
            return

        frame_id = frame.frame_id
        for trigger in skill.verbatim_triggers:
            if not trigger.on_activate:
                continue
            if tracker_handle.activate_trigger_already_fired(
                frame_id, trigger.response_name
            ):
                continue
            self._queue_response(
                response_name=trigger.response_name,
                tracker_handle=tracker_handle,
                source="activate",
                skill_id=skill_id,
            )
            tracker_handle.mark_activate_trigger_fired(frame_id, trigger.response_name)

    def evaluate_when_triggers(
        self,
        skill_id: str,
        flow_id: str,
        tracker_handle: TrackerHandle,
        *,
        memory_values_before: dict[str, Any] | None = None,
    ) -> None:
        """Queue skill ``utter:`` entries whose ``when:`` condition first matches."""
        skill = self._skill_catalog.skill_by_id(skill_id)
        if skill is None:
            return

        frame = tracker_handle.active_frame
        if frame is None:
            return

        frame_id = frame.frame_id
        memory_values = {
            slot_name: entry.value
            for slot_name, entry in tracker_handle.memory.read_all(
                skill_id, flow_id
            ).items()
        }

        for trigger in skill.verbatim_triggers:
            when = trigger.when_condition
            if when is None:
                continue

            matches_now = self._when_condition_matches(
                when, memory_values, skill_id, trigger.response_name
            )
            if memory_values_before is not None:
                matched_before = self._when_condition_matches(
                    when, memory_values_before, skill_id, trigger.response_name
                )
            else:
                matched_before = tracker_handle.when_trigger_matched_before(
                    frame_id, trigger.response_name
                )

            if matches_now and not matched_before:
                self._queue_response(
                    response_name=trigger.response_name,
                    tracker_handle=tracker_handle,
                    source="when",
                    skill_id=skill_id,
                    flow_id=flow_id,
                )

            tracker_handle.record_when_trigger_match(
                frame_id, trigger.response_name, matches_now
            )

    def _when_condition_matches(
        self,
        condition: Condition,
        memory_values: dict[str, Any],
        skill_id: str,
        response_name: str,
    ) -> bool:
        """Evaluate a ``when:`` condition, treating an unevaluable one as no match.

        Train-time validation rejects unparseable conditions, so this guards the
        runtime-only cases (e.g. ordering operators on incompatible value types).
        Fails closed: an utter that cannot be evaluated is not emitted.
        """
        try:
            return bool(evaluate_expression(condition, memory_values))
        except ConditionEvaluationError:
            structlogger.warning(
                "mantle.verbatim_trigger.when_eval_error",
                skill_id=skill_id,
                response_name=response_name,
            )
            return False

    def _queue_response(
        self,
        *,
        response_name: str,
        tracker_handle: TrackerHandle,
        source: str,
        tool_name: str | None = None,
        is_error: bool | None = None,
        skill_id: str | None = None,
        flow_id: str | None = None,
    ) -> None:
        """Resolve *response_name* and append it to the per-turn queue."""
        resolved = self._resolve_utterance(response_name, tracker_handle)
        if not resolved.text.strip():
            if source == "tool_outcome":
                structlogger.warning(
                    "mantle.tool_outcome.empty_resolved_utter",
                    tool_name=tool_name,
                    response_name=response_name,
                )
            else:
                structlogger.warning(
                    "mantle.verbatim_trigger.empty",
                    response_name=response_name,
                    source=source,
                )
            return

        if source == "tool_outcome":
            structlogger.info(
                "mantle.tool_outcome.queued",
                tool_name=tool_name,
                response_name=response_name,
                is_error=is_error,
            )
        elif source == "activate":
            structlogger.info(
                "mantle.verbatim_trigger.activate_queued",
                skill_id=skill_id,
                response_name=response_name,
            )
        elif source == "when":
            structlogger.info(
                "mantle.verbatim_trigger.when_queued",
                skill_id=skill_id,
                response_name=response_name,
            )

        scoped_skill, scoped_flow = tracker_handle.memory_scope()
        producing_skill = skill_id or scoped_skill
        producing_flow = flow_id or scoped_flow
        self._responses_this_turn.append(
            AgentResponse(
                text=resolved.text,
                mode=ResponseMode.CONTINUE,
                rephrase=resolved.rephrase,
                response_name=response_name,
                buttons=resolved.buttons,
                button_source=resolved.button_source,
                variant_metadata=resolved.variant_metadata,
                **button_source_scope_fields(
                    resolved.button_source,
                    producing_skill,
                    producing_flow,
                ),
            )
        )

    def _tool_gate_for(
        self, tool_name: str, tracker_handle: TrackerHandle
    ) -> Optional[GatedTool]:
        """Return the gate whose outcome utters apply to *tool_name*.

        Uses :meth:`SkillCatalog.effective_tool_gate` so a tool run from an
        ordered-block ``execute_tool`` step still resolves the skill-level
        ``on_success`` / ``on_failure`` names — flow-scoped gates alone are
        empty for a non-routable sub-flow.
        """
        skill_id, flow_id = tracker_handle.memory_scope()
        active_target_id = tracker_handle.active_flow_id or flow_id or ""
        return self._skill_catalog.effective_tool_gate(
            skill_id, active_target_id, tool_name
        )
